# 创建一个字符串工具模块
# 保存为 string_tools.py

def reverse(s):
    return s[::-1]

def is_palindrome(s):
    return s == s[::-1]

def word_count(s):
    return len(s.split())

def char_frequency(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    return freq

